// Grouped operational categories. These label actual receipts and spending,
// not transfers, credit-card settlements, or PAC contributions.
const BASE_CATEGORIES={
  income:[
    ['stipendio','Stipendio'],['bonus','Bonus e premi'],['rimborso','Rimborsi'],
    ['interessi','Interessi e proventi'],['vendita','Vendite e restituzioni'],
    ['apporto_comune','Contributi al conto comune'],['altro_entrata','Altre entrate']
  ],
  expense:[
    ['alimentari','Spesa alimentare'],['casa','Casa, affitto e condominio'],
    ['utenze','Bollette e utenze'],['trasporti','Auto, carburante e trasporti'],
    ['ristoranti','Ristoranti e bar'],['salute','Salute e farmacia'],
    ['shopping','Shopping e tecnologia'],['abbonamenti','Abbonamenti e telefonia'],
    ['viaggi','Viaggi e tempo libero'],['assicurazioni','Assicurazioni'],
    ['tasse','Tasse e imposte'],['formazione','Formazione'],['altro_spesa','Altre spese']
  ]
};
const UNCATEGORIZED='non_classificata';
function flowOfMovement(o){return o?.type==='income'?'income':(o?.type==='expense'||o?.type==='card_purchase')?'expense':null;}
function categoryItems(type){
  return [[UNCATEGORIZED,'Da categorizzare'],...(BASE_CATEGORIES[type]||[]),
    ...(state.customCategories||[]).filter(c=>c.type===type).map(c=>[c.id,c.label])];
}
function categoryLabel(o){
  const type=flowOfMovement(o);if(!type)return '';
  return categoryItems(type).find(v=>v[0]===(o.category||UNCATEGORIZED))?.[1]||'Categoria precedente';
}
function cleanMovementCategory(o){
  const type=flowOfMovement(o);if(!type)return null;
  const cat=String(o.category||UNCATEGORIZED);
  // Keep legacy categories if a custom category was removed accidentally.
  return categoryItems(type).some(([id])=>id===cat)?cat:UNCATEGORIZED;
}
function movementScope(o){
  if(o.type==='card_purchase')return 'personal';
  return (o.to==='sella'||o.from==='sella')?'shared':'personal';
}
function showCategoryOption(type,field,value){
  return select('Categoria',field,categoryItems(type),value||UNCATEGORIZED);
}

