function addMovement(){
  const opts=[['income','Entrata sul conto'],['expense','Uscita / spesa'],['transfer','Trasferimento tra conti'],['investment','Incremento PAC / fondo pensione'],['card_purchase','Acquisto con carta di credito']];
  const accountOptions=state.accounts.map(a=>[a.id,a.name]);
  const sourceOptions=[...accountOptions,['external','Trattenuta busta paga / TFR / datore']];
  const investmentsOptions=state.investments.map(a=>[a.id,a.name]);
  const show=(when,html,cls='')=>`<div class="movement-slot ${cls}" data-move-show="${when}" hidden>${html}</div>`;
  const form=
    input('Data operazione','date','date',dNow(),`required`)+
    select('Tipologia movimento','type',opts,'transfer')+
    input('Importo (€)','amount','number','','min="0.01" step="0.01" required')+
    show('expense transfer',select('Conto di partenza','from',accountOptions,'allianz'))+
    show('income transfer',select('Conto di destinazione','to',accountOptions,'sella'))+
    show('investment',select('Conto di uscita','source',sourceOptions,'allianz'))+
    show('investment',select('PAC / fondo pensione di destinazione','assetId',investmentsOptions,'jpm'))+
    show('investment',`<details class="movement-advanced"><summary>Dettagli dell’investimento (facoltativi)</summary><div class="movement-advanced-fields">${input('Quote realmente acquistate','units','number','','min="0" step="0.00000001"','Lascia vuoto se non le conosci ancora.')}${input('Costo d’ingresso (%)','fee','number','0','min="0" max="100" step="0.01"')}</div></details>`,'full')+
    input('Descrizione (facoltativa)','note','text','','maxlength="120"')+
    `<div class="full insight movement-context" data-move-help aria-live="polite"></div>`;
  modal('Nuovo movimento','Seleziona la tipologia: vedrai solo i campi necessari.',form,'Registra movimento',fd=>{
    const date=mustAnyDate(fd,'date'), amount=mustMoney(fd,'amount'),type=forField(fd,'type'),note=forField(fd,'note');
    if(!positive(amount))throw Error('Inserisci un importo maggiore di zero.');
    const accountExists=id=>state.accounts.some(a=>a.id===id);
    if(type==='income'){
      const to=forField(fd,'to');
      if(!accountExists(to))throw Error('Seleziona il conto di destinazione.');
      state.movements.push({id:newId(),date,type,amount,to,note,status:statusForDate(date)});
    }else if(type==='expense'){
      const from=forField(fd,'from');
      if(!accountExists(from))throw Error('Seleziona il conto di partenza.');
      state.movements.push({id:newId(),date,type,amount,from,note,status:statusForDate(date)});
    }else if(type==='transfer'){
      const from=forField(fd,'from'),to=forField(fd,'to');
      if(!accountExists(from)||!accountExists(to))throw Error('Seleziona entrambi i conti.');
      if(from===to)throw Error('I due conti devono essere diversi.');
      state.movements.push({id:newId(),date,type,amount,from,to,note,status:statusForDate(date)});
    }else if(type==='investment'){
      const source=forField(fd,'source'),assetId=forField(fd,'assetId');
      const units=safeNum(fd.get('units')),fee=safeNum(fd.get('fee'))??0;
      if(!accountExists(source)&&source!=='external')throw Error('Seleziona il conto di uscita.');
      if(!state.investments.some(a=>a.id===assetId))throw Error('Seleziona il PAC o fondo pensione.');
      if(units!==null&&units<0)throw Error('Le quote non possono essere negative.');
      if(fee<0||fee>100)throw Error('Il costo d’ingresso deve essere compreso tra 0% e 100%.');
      const existing=generateRecurring(state,date).some(z=>z.assetId===assetId&&z.date===date&&z.status!=='skipped');
      if(existing&&!confirm('Alla stessa data è già prevista una rata automatica per questo investimento. Questa è un’operazione aggiuntiva, distinta dalla rata programmata?'))return false;
      state.movements.push({id:newId(),date,type,assetId,source,amount,units,feePercent:fee,status:statusForDate(date),note});
    }else if(type==='card_purchase'){
      state.movements.push({id:newId(),date,type,amount,note,status:statusForDate(date)});
    }else throw Error('Tipologia non riconosciuta.');
    persist();notify(date>dNow()?'Operazione futura: verrà contabilizzata automaticamente dal '+fmtDate(date)+', senza conferma. Premi Salva.':date<START_DATE?'Operazione anteriore alla data zero: registrata solo per memoria.':'Movimento registrato. Premi Salva in alto per scriverlo sul PC.');
  });
  refreshMovementFields();
}

