    fieldCategory('income','categoryIncome')+fieldCategory('expense card_purchase','categoryExpense')+
    show('card_payment',input('Mese degli acquisti (AAAA-MM)','period','month',period,'required'))+
    input('Descrizione (facoltativa)','note','text',record?.note||'','maxlength="120"')+
    `<div class="full insight movement-context" data-move-help aria-live="polite"></div>`+
