}
function parseMovementForm(fd,previous=null){
  const date=mustAnyDate(fd,'date'),amount=mustMoney(fd,'amount');
  const type=forField(fd,'type'),note=forField(fd,'note');
  if(!positive(amount))throw Error('Inserisci un importo maggiore di zero.');
  if(previous?.type==='card_payment'&&type!=='card_payment')throw Error('Il pagamento della carta va mantenuto come pagamento.');
  const rec={id:previous?.id||newId(),date,type,amount,note,
    status:date<START_DATE?'historical':date>dNow()?'planned':
      previous?.status==='skipped'?'skipped':previous?.status==='planned'?'planned':'confirmed'};
  const validAccount=id=>state.accounts.some(a=>a.id===id);
  if(type==='income'){
    rec.to=forField(fd,'to');if(!validAccount(rec.to))throw Error('Seleziona un conto di destinazione.');
    rec.category=forField(fd,'categoryIncome')||UNCATEGORIZED;
    if(previous?.origin==='partner'&&rec.to==='sella')rec.origin='partner';
  }else if(type==='expense'){
    rec.from=forField(fd,'from');if(!validAccount(rec.from))throw Error('Seleziona un conto di partenza.');
    rec.category=forField(fd,'categoryExpense')||UNCATEGORIZED;
  }else if(type==='transfer'){
    rec.from=forField(fd,'from');rec.to=forField(fd,'to');
    if(!validAccount(rec.from)||!validAccount(rec.to)||rec.from===rec.to)throw Error('Indica due conti diversi.');
  }else if(type==='investment'){
    rec.source=forField(fd,'source');rec.assetId=forField(fd,'assetId');
    if(!validAccount(rec.source)&&rec.source!=='external')throw Error('Seleziona la fonte del versamento.');
    if(!state.investments.some(a=>a.id===rec.assetId))throw Error('Seleziona il PAC o fondo pensione.');
    const units=safeNum(fd.get('units')),fee=safeNum(fd.get('fee'))??0;
    if(units!==null&&units<0)throw Error('Le quote non possono essere negative.');
    if(fee<0||fee>100)throw Error('Il costo deve essere compreso tra 0 e 100%.');
    rec.units=units;rec.feePercent=fee;
    const previouslySame=previous?.type==='investment'&&previous?.assetId===rec.assetId&&previous?.date===rec.date;
    const planned=generateRecurring(state,date).some(z=>z.assetId===rec.assetId&&z.date===date&&z.status!=='skipped');
    if(planned&&!previouslySame&&!confirm('Per questo investimento esiste già una rata programmata nella stessa data. È davvero un versamento aggiuntivo?'))return null;
  }else if(type==='card_purchase'){
    rec.category=forField(fd,'categoryExpense')||UNCATEGORIZED;
  }else if(type==='card_payment'){
    rec.from='allianz';rec.period=forField(fd,'period');
    if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(rec.period))throw Error('Periodo carta non valido.');
  }else throw Error('Tipologia non riconosciuta.');
  if(flowOfMovement(rec) && !categoryItems(flowOfMovement(rec)).some(([id])=>id===rec.category)){
    throw Error('Categoria non valida, seleziona una delle voci disponibili.');
  }
  return rec;
}
function validateEditedMovement(candidate,previous){
  if(candidate.type!=='card_payment'&&previous?.type!=='card_payment'&&
    candidate.type!=='card_purchase'&&previous?.type!=='card_purchase')return;
  const moves=previous?state.movements.map(z=>z.id===previous.id?candidate:z):[...state.movements,candidate];
  const draft={...state,movements:moves};
  const checkDate=candidate.date>dNow()?candidate.date:dNow();
  const liabilities=computeAt(draft,checkDate).card;
  if(Object.values(liabilities.byPeriod).some(v=>v<-0.01))
    throw Error('Questa modifica farebbe risultare un periodo della carta pagato oltre il debito. Verifica anche gli addebiti già registrati.');
}
function openMovementEditor(id=null){
  const previous=id?state.movements.find(o=>o.id===id):null;
  if(id&&!previous)throw Error('Movimento non trovato nel registro locale.');
  modal(previous?'Modifica movimento':'Nuovo movimento',
    previous?'Modifica data, importo, conto, categoria o descrizione. Nessun movimento duplicato.':'I campi cambiano in base alla tipologia.',
    movementEditorFields(previous),previous?'Salva modifiche':'Registra movimento',fd=>{
      const next=parseMovementForm(fd,previous);if(!next)return false;
      validateEditedMovement(next,previous);
      if(previous){const index=state.movements.findIndex(o=>o.id===previous.id);state.movements[index]=next;}
      else state.movements.push(next);
      persist();
      notify(previous?'Movimento modificato; premi Salva per aggiornare il JSON.':
        next.date>dNow()?'Operazione futura: sarà conteggiata dalla data prevista. Premi Salva.':
        next.date<START_DATE?'Movimento precedente alla data zero: conservato nello storico.':
        'Movimento registrato; premi Salva.');
    });
  refreshMovementFields();
}
function addMovement(){openMovementEditor();}
function editMovement(id){openMovementEditor(id);}

function reportEvents(data,period,scope){
  return (data.movements||[]).filter(z=>{
    if(z.date<START_DATE||z.date>dNow()||z.status==='skipped'||z.status==='historical')return false;
    if(!flowOfMovement(z))return false;
    if(period!=='all'&&monthKey(z.date)!==period)return false;
    if(scope!=='all'&&movementScope(z)!==scope)return false;
    return true;
  });
}
function summarizeCategories(data,period,scope,flow){
  const rows=reportEvents(data,period,scope).filter(z=>flow==='both'||flowOfMovement(z)===flow);
  const groups=new Map();
  for(const z of rows){
    const kind=flowOfMovement(z),category=cleanMovementCategory(z)||UNCATEGORIZED;
    const key=kind+'|'+category;
    if(!groups.has(key))groups.set(key,{type:kind,category,label:categoryLabel(z),total:0,count:0,estimated:0});
    const g=groups.get(key);g.total+=Number(z.amount)||0;g.count++;
    if(z.status==='planned')g.estimated++;
  }
  const income=rows.filter(z=>flowOfMovement(z)==='income').reduce((sum,z)=>sum+Number(z.amount||0),0);
  const expense=rows.filter(z=>flowOfMovement(z)==='expense').reduce((sum,z)=>sum+Number(z.amount||0),0);
  return {income:eurRound(income),expense:eurRound(expense),count:rows.length,
    unverified:rows.filter(z=>z.status==='planned').length,
    groups:[...groups.values()].map(g=>({...g,total:eurRound(g.total)}))
      .sort((a,b)=>b.total-a.total||a.label.localeCompare(b.label,'it'))};
}
