  const form=select('Tipologia','type',[['expense','Uscita'],['income','Entrata']],'expense')+
    input('Nome categoria','label','text','','maxlength="48" required');
  modal('Nuova categoria','Disponibile nei menu dei movimenti e nei report.',form,'Aggiungi categoria',fd=>{
    const type=forField(fd,'type'),label=forField(fd,'label').replace(/\s+/g,' ').trim();
    if(!['expense','income'].includes(type)||label.length<2||label.length>48)throw Error('Indica un nome di 2–48 caratteri.');
    if(categoryItems(type).some(([,name])=>name.toLowerCase()===label.toLowerCase()))throw Error('Questa categoria esiste già.');
    state.customCategories=state.customCategories||[];
    state.customCategories.push({id:'custom_'+type+'_'+newId().replace(/[^A-Za-z0-9]/g,'').slice(-15),type,label});
    persist();notify('Categoria aggiunta. Premi Salva.');
  });
}
function deleteCustomCategory(id){
  const cat=(state.customCategories||[]).find(c=>c.id===id);if(!cat)return;
  if(state.movements.some(z=>z.category===id))return alert('Categoria utilizzata da un movimento: prima cambia la categoria di quei movimenti.');
  if(!confirm('Eliminare la categoria '+cat.label+'?'))return;
  state.customCategories=state.customCategories.filter(c=>c.id!==id);
  persist();notify('Categoria eliminata. Premi Salva.');
}
function exportReport(){
  const rows=reportEvents(state,reportPeriod,reportScope)
    .filter(z=>reportFlow==='both'||flowOfMovement(z)===reportFlow)
    .sort((a,b)=>a.date.localeCompare(b.date))
    .map(z=>[z.date,flowOfMovement(z)==='income'?'Entrata':'Uscita',categoryLabel(z),z.note||'',z.amount,movementScope(z)==='shared'?'Comune':'Personale',z.status==='planned'?'Da verificare':'Registrato']);
  downloadText(`MyWealth_report_${reportPeriod}_${reportScope}.csv`,csvRows([['Data','Tipo','Categoria','Descrizione','Importo EUR','Ambito','Stato'],...rows]),'text/csv;charset=utf-8');
  notify('Report per categoria esportato.');
}

